CREATE TABLE IF NOT EXISTS entity_registry (id TEXT PRIMARY KEY, entity_type TEXT NOT NULL, first_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, last_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS projects (entity_id TEXT PRIMARY KEY REFERENCES entity_registry(id) ON DELETE RESTRICT, display_name TEXT NOT NULL CHECK(length(display_name) BETWEEN 1 AND 120), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sites (entity_id TEXT PRIMARY KEY REFERENCES entity_registry(id), project_id TEXT NOT NULL REFERENCES projects(entity_id), display_name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS network_contexts (entity_id TEXT PRIMARY KEY REFERENCES entity_registry(id), project_id TEXT NOT NULL REFERENCES projects(entity_id), site_id TEXT REFERENCES sites(entity_id), display_name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS discovery_scopes (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(entity_id), scope_kind TEXT NOT NULL CHECK(scope_kind IN ('cidr','single_ip','seed_device','site_context')), target TEXT NOT NULL CHECK(length(target) BETWEEN 1 AND 255), enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS scan_profiles (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(entity_id), name TEXT NOT NULL, read_only INTEGER NOT NULL DEFAULT 1 CHECK(read_only = 1), active_probe_enabled INTEGER NOT NULL DEFAULT 0 CHECK(active_probe_enabled = 0));
CREATE TABLE IF NOT EXISTS credential_references (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(entity_id), protocol TEXT NOT NULL, label TEXT NOT NULL, secret_store_key TEXT NOT NULL CHECK(length(secret_store_key) BETWEEN 1 AND 255), validation_state TEXT NOT NULL DEFAULT 'unknown');
CREATE TABLE IF NOT EXISTS scan_sessions (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(entity_id), profile_id TEXT NOT NULL REFERENCES scan_profiles(id), state TEXT NOT NULL CHECK(state IN ('requested','preflight','running','completed','failed','cancelled','interrupted','rejected')), provider_name TEXT NOT NULL, started_at TEXT, finished_at TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS one_running_scan_per_project ON scan_sessions(project_id) WHERE state = 'running';
CREATE TABLE IF NOT EXISTS devices (entity_id TEXT PRIMARY KEY REFERENCES entity_registry(id), project_id TEXT NOT NULL REFERENCES projects(entity_id), display_name TEXT NOT NULL, device_type TEXT NOT NULL DEFAULT 'unknown');
CREATE TABLE IF NOT EXISTS network_adapters (entity_id TEXT PRIMARY KEY REFERENCES entity_registry(id), device_entity_id TEXT NOT NULL REFERENCES devices(entity_id), name TEXT NOT NULL, adapter_kind TEXT NOT NULL CHECK(adapter_kind IN ('physical','virtual','unknown')));
CREATE TABLE IF NOT EXISTS interfaces (entity_id TEXT PRIMARY KEY REFERENCES entity_registry(id), device_entity_id TEXT NOT NULL REFERENCES devices(entity_id), network_adapter_entity_id TEXT REFERENCES network_adapters(entity_id), name TEXT NOT NULL, interface_kind TEXT NOT NULL CHECK(interface_kind IN ('physical','virtual','vlan','svi','bridge','bond','lag','tunnel','loopback')), physical_port_state TEXT NOT NULL DEFAULT 'not_observed' CHECK(physical_port_state IN ('evidence','not_observed','logical_only')), UNIQUE(device_entity_id,name));
CREATE TABLE IF NOT EXISTS evidence (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(entity_id), target_entity_id TEXT NOT NULL REFERENCES entity_registry(id), attribute TEXT NOT NULL, source_type TEXT NOT NULL, confidence REAL NOT NULL CHECK(confidence BETWEEN 0 AND 1), observed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, value_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS entity_overrides (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(entity_id), target_entity_id TEXT NOT NULL REFERENCES entity_registry(id), attribute TEXT NOT NULL, value_json TEXT NOT NULL, actor TEXT NOT NULL DEFAULT 'local_user', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS physical_links (entity_id TEXT PRIMARY KEY REFERENCES entity_registry(id), source_interface_entity_id TEXT NOT NULL REFERENCES interfaces(entity_id), target_interface_entity_id TEXT NOT NULL REFERENCES interfaces(entity_id), assertion_state TEXT NOT NULL CHECK(assertion_state IN ('known','inferred','unknown','user_confirmed')), evidence_id TEXT NOT NULL REFERENCES evidence(id), CHECK(source_interface_entity_id < target_interface_entity_id));
CREATE TRIGGER IF NOT EXISTS physical_link_requires_evidenced_physical_ports BEFORE INSERT ON physical_links FOR EACH ROW WHEN EXISTS (SELECT 1 FROM interfaces WHERE entity_id=NEW.source_interface_entity_id AND (interface_kind<>'physical' OR physical_port_state<>'evidence')) OR EXISTS (SELECT 1 FROM interfaces WHERE entity_id=NEW.target_interface_entity_id AND (interface_kind<>'physical' OR physical_port_state<>'evidence')) BEGIN SELECT RAISE(ABORT, 'physical links require evidenced physical interface endpoints'); END;
CREATE TABLE IF NOT EXISTS device_inventory_projections (device_entity_id TEXT PRIMARY KEY REFERENCES devices(entity_id) ON DELETE CASCADE, project_id TEXT NOT NULL REFERENCES projects(entity_id), network_context_id TEXT REFERENCES network_contexts(entity_id), sort_name TEXT NOT NULL, device_type TEXT NOT NULL, primary_ip_display TEXT, connection_state TEXT NOT NULL CHECK(connection_state IN ('known','inferred','unknown')), connection_summary TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'unknown', last_seen_at TEXT, refreshed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS inventory_projection_sort ON device_inventory_projections(project_id,sort_name,last_seen_at DESC);
CREATE TABLE IF NOT EXISTS audit_trail (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(entity_id), action TEXT NOT NULL, actor TEXT NOT NULL DEFAULT 'local_user', detail_json TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
